require __DIR__.'/../includes/config.php';require __DIR__.'/../includes/functions.php';$u=require_role(['owner']);$st=$pdo->prepare('SELECT n.*,r.request_no FROM notifications n LEFT JOIN requests r ON r.id=n.request_id WHERE n.user_id=? ORDER BY n.created_at DESC');$st->execute([$u['id']]);$rows=$st->fetchAll();$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$u['id']]);$pageTitle='Notifications';require __DIR__.'/../includes/header.php';?>
<div class="eyebrow">STAY INFORMED</div><h2>Notifications</h2><p class="subtext">Updates from your township assistance requests.</p><div class="grid"><?php if(!$rows):?><div class="card empty">No notifications yet. Request updates will appear here.</div><?php else:foreach($rows as $n):?><div class="card"><div style="display:flex;gap:12px"><div class="category-icon cat-plumbing">♧</div><div style="flex:1"><strong><?=e($n['title'])?></strong><p class="muted" style="margin:6px 0"><?=e($n['body'])?></p><small class="muted"><?=e(status_timestamp($n['created_at']))?><?= $n['request_no']?' · '.e($n['request_no']):'' ?></small></div></div></div><?php endforeach;endif;?></div><?php require __DIR__.'/../includes/footer.php';?>
